mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, sec.Sec_Name as secName, c1.C_Name_History as glsWarranteeNameHistory, c3.C_Name_History as glsBeneficiaryNameHistory, c1.C_Name as glsWarranteeName, c3.C_Name as glsBeneficiaryName, c1.C_Abbreviation as glsWarranteeAbbName, c3.C_Abbreviation as glbCompanyAbbName, f.file_relation_id as fileRelationId, glb.Glb_Id as glbId, glb.Glb_State as glbState, glb.Glb_Create_Uid as glbCreateUid, glb.Glb_Date as glbDate, glb.Glb_Company_Id as glbCompanyId, con.Con_Plan_Start_Date as conPlanStartDate, con.Con_Plan_End_Date as conPlanEndDate, c2.C_Name as glbCompanyName, panya.c_name as companyPartyAName, panyb.c_name as companyPartybName, con.Con_Money_Total as conMoneyTotal, con.Con_Ac_Money as conAcMoney, mn.* from Guarantee_Letter_Sign mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_Company c1 on mn.Gls_Warrantee=c1.C_Id left join Sys_File f on f.FileID=mn.Gls_Id left join SYS_Company c3 on mn.Gls_Beneficiary=c3.C_Id left join Guarantee_Letter_Back glb on glb.Gls_Id=mn.Gls_Id and glb.Glb_State!=3 left join SYS_Company c2 on glb.Glb_Company_Id=c2.C_Id left join sys_company panya ON con.Con_Party_A_Id = panya.c_id left join sys_company panyb ON con.Con_Party_B_Id = panyb.c_id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Gls_Create_Time desc
